def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    players = 1 + len(alive_opponents)
    total_need = players * WATER_REQ
    scarcity = total_need - supply

    if len(alive_opponents) == 0:
        return max(0, min(budget, round(DAILY_SALARY * 0.25, 2)))

    if hp <= 1:
        base = DAILY_SALARY * 0.98
    elif hp <= 2 or no_water >= 1:
        base = DAILY_SALARY * 0.9
    elif scarcity <= 0:
        base = DAILY_SALARY * 0.38
    elif scarcity <= WATER_REQ:
        base = DAILY_SALARY * 0.52
    else:
        base = DAILY_SALARY * 0.68

    if desperate_count >= max(1, len(alive_opponents) // 2):
        base += 6
    if rich_count >= max(1, len(alive_opponents) // 2):
        base += 4

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        if hp <= 2 or no_water >= 1:
            base = max(base, highest_prev + 2.0)
        elif scarcity > 0:
            base = max(base, avg_prev + 1.0)
        else:
            base = min(base, highest_prev)

    if budget < DAILY_SALARY * 0.6 and hp > 2 and no_water == 0:
        base *= 0.8

    bid = max(0, min(budget, base))
    return round(bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    budget = float(my_status.get('budget', 0.0))
    hp = float(my_status.get('hp', 0.0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # Immediate reaction to yesterday's behavior (only previous_trace)
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    # Baseline bid sizing: tie to supply pressure but keep conservative
    # If supply is low, we bid slightly higher to secure enough water.
    # Ensure bid does not exceed budget.
    if supply <= MIN_SUPPLY:
        base = DAILY_SALARY * 0.60
    elif supply >= MAX_SUPPLY:
        base = DAILY_SALARY * 0.45
    else:
        # Linear interpolation between MIN_SUPPLY and MAX_SUPPLY
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        base = (DAILY_SALARY * 0.60) * (1.0 - t) + (DAILY_SALARY * 0.45) * t

    # Counter if opponents were aggressive yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone was bidding close to our daily salary, they likely value survival.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if hp > 3:
                bid = DAILY_SALARY * 0.75
            else:
                bid = DAILY_SALARY * 0.95
        else:
            # Match slightly above their typical pressure, but remain budget-safe
            bid = max(base, highest_prev_bid + 1.5)
    else:
        # No trace info: moderate bid; increase if hp is low
        if hp <= 2:
            bid = DAILY_SALARY * 0.90
        elif hp <= 3:
            bid = DAILY_SALARY * 0.70
        else:
            bid = base

    # Convert to final bid within budget and non-negative
    if budget <= 0:
        return 0.0
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

